  CollectionHall_100460_Desc = {
    Text = "\"Je l'ai déjà dit, peu importe les moyens, je ramènerai tout le monde chez soi.\"\n\"Je brûlerai tout ce qui m’appartient, et puis...\n\"Avec cet enfer des étoiles, je réduirai ce faux, sale et chaotique monde en cendres !\"\n\"Je le déclare au nom de Kathigu-Ra !\"\n\"Le jour se lèvera !\""
