  CollectionHall_100460_Title = {
    Text = "L'aube qui brûle tout"
  },
  CollectionHall_100461_Desc = {
    Text = "La folie de la mort tourbillonne comme un kaléidoscope, le doux parfum métallique émanant de la maladie et des cadavres est le meilleur encens. Vous levez vos coupes de loin, séparés par d'innombrables âmes se dirigeant vers leur destinée—si la mort est destinée, laissons-nous nous précipiter joyeusement vers ce bal, et ensemble, avec le dernier battement de la danse, plongeons dans les portes de l'Enfer."
  },
  CollectionHall_100461_LockTip = {
