  CollectionHall_100462_LockTip = {
    Text = "Complète \"Banquet en Flammes\" dans Les Errants"
  },
  CollectionHall_100462_Title = {
    Text = "Reine des désolations"
  },
  CollectionHall_100463_Desc = {
    Text = "Elle est déchaînée, violente et capricieuse, mais elle est aussi bienveillante, érudite et pleine de sagesse.\nElle est le tyran de la débauche et la protectrice des agneaux ; elle vous accorde l'amour et vous accorde aussi la mort. Tous les êtres vivants sur cette terre doivent ramper à ses pieds, appelant respectueusement son nom.\nOffrez-vous au bal de la Reine, et ensuite, ensemble avec elle, plongez dans la flamme noire éternelle."
  },
  CollectionHall_100463_LockTip = {
    Text = "Complète \"Banquet en Flammes\" dans Les Errants"
  },
  CollectionHall_100463_Title = {
    Text = "Un toast à la mort"
  },
  CollectionHall_100464_Desc = {
    Text = "Si tu ne peux faire qu'une dernière chose avant de mourir, alors danse.\n Bois le vin doux, dévore la délicieuse viande rôtie, et tourbillonne librement dans la fête de la musique.\n Que le dernier reflet de ce monde dans tes yeux scintille encore d'une lumière dorée enivrante."
  },
  CollectionHall_100464_LockTip = {
    Text = "Complète \"Banquet en Flammes\" à la difficulté Difficile dans Les Errants"
