  CollectionHall_100465_Desc = {
    Text = "Elle voit toujours le glorieux passé dans le lac.\nLes souvenirs rongés sont comme de faux rêves ; dans le rêve, elle est assise au milieu des ruines infinies, témoignant de tout ce qui lui appartient s'effaçant comme des fantômes.\nLorsque même ce rêve sera oublié, le flûtiste viendra à travers la brume, la guidant vers le chemin de retour pour les défunts."
  },
  CollectionHall_100465_LockTip = {
