    Text = "Madame Mosk a dit fermement que c'était une relique. \n «Méchant, mords-le !»"
  },
  CollectionHall_118631_LockTip = {
    Text = "Déverrouillable dans l'événement « L'appel de Merscus »"
  },
  CollectionHall_118631_Title = {
    Text = "<OrangeQuality:Petit charbon II>"
  },
  CollectionHall_118633_Desc = {
    Text = "«La Lune Sanglante se lève, les cadavres doivent lever leur verre et boire ensemble.»"
  },
  CollectionHall_118633_LockTip = {
    Text = "Peut être déverrouillé dans l'événement « Esthétique nécrotique »"
  },
  CollectionHall_118633_Title = {
    Text = "<OrangeQuality:Calice d'Os>"
  },
  CollectionHall_118636_Desc = {
    Text = "Les mots sur la lettre changent continuellement, se transformant toujours en un désir irréfusable."
  },
  CollectionHall_118636_LockTip = {
    Text = "Débloqué dans l'événement « Ombre de la ville pluvieuse »"
  },
  CollectionHall_118636_Title = {
    Text = "<OrangeQuality:Invitation aux Mille Visages>"
  },
  CollectionHall_120344_Title = {
    Text = "Nous nous retrouverons enfin"
  },
  CollectionHall_120463_LockTip = {
    Text = "Débloqué dans : Chapitre 4–15"
  },
  CollectionHall_120463_Title = {
    Text = "Enregistrer sans culpabilité"
  },
  CollectionHall_120464_LockTip = {Text = "À suivre"},
  CollectionHall_120464_Title = {
    Text = "Porte-monnaie gourmand"
  },
  CollectionHall_120465_LockTip = {
    Text = "Débloqué dans : Chapitre 4-5"
  },
  CollectionHall_120465_Title = {Text = "Craquement"},
  CollectionHall_120466_LockTip = {
    Text = "Débloqué dans : Chapitre 3–10"
  },
  CollectionHall_120466_Title = {
    Text = "Télégramme silencieux"
  },
  CollectionHall_121154_Title = {Text = "Paradis"},
  CollectionHall_121341_Desc = {
    Text = "<Title:Introduction>\nLa « princesse » qui accepte la responsabilité de donner naissance à « l'Enfant Saint » est désormais la « Mère divine » d'une grande importance au sein du culte des Marins.\nElle a également été une demoiselle courant vers la liberté, empruntant le même chemin de fuite que Murphy, consigné par Mizag, à bord du Sonanir.\nMais dans un monde sans Gardien, le destin a brisé le cou noble du jeune cygne.\nUn sang tordu l'entrave sans relâche, sans possibilité de résistance, même la mort de son corps ne peut lui épargner. Elle se force à dire encore et encore « Je suis la précieuse Mère divine », ce n'est qu'une suggestion et une persuasion pour elle-même.\nElle ne peut que se soumettre, uniquement se soumettre. Se soumettre à l'illusoire oracle divin, se soumettre à un destin absurde, puis, à partir de l'amertume infinie, elle parvient à goûter péniblement cette douce illusion."
  },
  CollectionHall_121341_LockTip = {
    Text = "Débloqué après avoir réveillé « Délire·Murphy »"
  },
  CollectionHall_121341_Title = {
    Text = "Murphy : faux né"
  },
  CollectionHall_121381_Desc = {
    Text = "Tu as échangé mille glands contre une histoire venue d'une autre dimension.\nUne histoire de héros et de démons, de veille et de persévérance.\nUne histoire de résignation et de regrets, d'anciens amis et de nouveaux amis.\nUne histoire qui a autrefois existé."
  },
  CollectionHall_121381_LockTip = {
    Text = "Compléter la connexion multidimensionnelle «Tour inverse»"
  },
  CollectionHall_121381_Title = {
    Text = "Écho de l'auberge des mille phénomènes"
  },
  CollectionHall_121382_Desc = {
    Text = "Longtemps après, lui et lui eurent enfin une ballade chantée. \n À propos de la rédemption de la renaissance, à propos des âmes jumeaux."
  },
  CollectionHall_121382_LockTip = {
    Text = "Terminez le paysage de rêve « Au-delà de l'horizon · bas »"
  },
  CollectionHall_121382_Title = {
    Text = "Poème de l'oiseau sans ailes"
  },
  CollectionHall_121383_Desc = {
    Text = "Le jeune homme a payé le prix de ce qui est éphémère. \n Aujourd'hui, il ne reste que le pouvoir silencieux à ses côtés. \n Le roi s'apprête à s'endormir, il accueille la fin du monde dans ses rêves."
  },
  CollectionHall_121383_LockTip = {
    Text = "Terminez le vagabond « Jour du couronnement »"
  },
  CollectionHall_121383_Title = {
    Text = "Royauté éternelle de douleur infinie"
  },
  CollectionHall_121384_Desc = {
    Text = "Elles t'entourent, elles t'admirent, elles t'accompagnent.\nElles lèvent les voiles vers le Dieu créateur."
  },
  CollectionHall_121384_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-11"
  },
  CollectionHall_121384_Title = {
    Text = "Lever les voiles vers le Dieu Créateur"
  },
  CollectionHall_121385_Desc = {
    Text = "C'étaient des ailes renaissant de la destruction, des ailes acquises par le sacrifice pour la liberté. \n La prédiction du destin s'est réalisée, il a juré dans la douleur et le regret que le sang doit être payé par du sang."
  },
  CollectionHall_121385_LockTip = {
    Text = "Terminez «Au-delà de l'horizon · bas» dans le paysage de rêve"
  },
  CollectionHall_121385_Title = {
    Text = "Lorsque la tempête se lève"
  },
  CollectionHall_121386_Desc = {
    Text = "Dans le rêve absurde et chaotique, dès le début, Il était destiné à affronter son destin.\nMais Il a enduré et défini trop de choses.\nIl a résolu de contempler ses origines avec la plus grande rationalité que l'humanité puisse maintenir, cette divinité suprême."
  },
  CollectionHall_121386_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-11"
  },
  CollectionHall_121386_Title = {
    Text = "Guerre du Destin Originel"
  },
  CollectionHall_121387_Desc = {
    Text = "Gagner, perdre, couper, sacrifier. \n Le héros a payé le prix de tout, et protéger l'autorité précieuse est sa récompense."
  },
  CollectionHall_121387_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-13"
  },
  CollectionHall_121387_Title = {
    Text = "Œil sans pupille"
  },
  CollectionHall_121388_Desc = {
    Text = "Il se couronna, il se mit enchaîné. \n C'était une chaleur momentanée et illusoire, c'était la gloire vouée à l'échec du passé."
  },
  CollectionHall_121388_LockTip = {
    Text = "Terminez le vagabond « Jour du couronnement »"
  },
  CollectionHall_121388_Title = {
    Text = "Le chemin solitaire du jeune roi"
  },
  CollectionHall_121389_Desc = {
    Text = "Malgré la situation défavorable, le coin de votre bouche s'est légèrement levé. \n \"Mon tour, pioche !\" \n Que ce soit dans l'Auberge des mille phénomènes ou à Mizag, \n sous-estimer la capacité de dégâts des soutiens peut entraîner des pertes significatives ! Ignatius !"
  },
  CollectionHall_121389_LockTip = {
    Text = "Finaliser la connexion multidimensionnelle «Tour inverse»"
  },
  CollectionHall_121389_Title = {
    Text = "Mon instant d'inversion !"
  },
  CollectionHall_121390_Desc = {
    Text = "Une légende complète ne peut se passer de transformer des ennemis en amis."
  },
  CollectionHall_121390_LockTip = {
    Text = "Débloqué après avoir terminé la mission d'enquête · Difficile 9-10"
  },
  CollectionHall_121390_Title = {
    Text = "ennemi, ami"
  },
  CollectionHall_121391_Desc = {
    Text = "Désormais, tu te tiens en tant que Gardien parmi la multitude d'étudiants et d'érudits du Mizag."
  },
  CollectionHall_121391_LockTip = {
    Text = "Débloqué après avoir terminé Mission d'enquête·Difficile 9-11"
  },
  CollectionHall_121392_Desc = {
    Text = "Nous sommes peut-être des instants éphémères dans l'éternité, des grains de sable dans le torrent.\nCependant, le monde éternel est notre précieuse éternité, car peu importe à quel point le monde devient fou et chaotique—\nla dignité humaine sera établie sur l'éclat de la raison."
  },
  CollectionHall_121392_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-11"
  },
  CollectionHall_121392_Title = {
    Text = "Chant des Temps Éternels"
  },
  CollectionHall_121393_Desc = {
    Text = "Les héros se sont précipités dans des contes de fées, chaque conte étant le même, avec des animaux, des démons, des fées et l'inconnu au-delà. \n Au-delà d'une brève liberté et d'un désir illusoire, à la fin du conte de fées se cache un cœur illusoire qui lui a été imposé."
  },
  CollectionHall_121393_LockTip = {
    Text = "Terminez le paysage de rêve « Au-delà de l'horizon · bas »"
  },
  CollectionHall_121393_Title = {
    Text = "Voler dans la Voie lactée"
  },
  CollectionHall_121394_Desc = {
    Text = "Ici se trouve l'Auberge des mille phénomènes, située dans une faille spatio-temporelle d'un monde étranger. \n Des portes de téléportation, connectant différents univers, scintillent sous l'immensité des étoiles, t'accueillant. \n Attends... Que fais-tu ici, Gardien ?"
  },
  CollectionHall_121394_LockTip = {
    Text = "Fin de la connexion multidimensionnelle «Tour inverse»"
  },
  CollectionHall_121394_Title = {
    Text = "Bienvenue à l'Auberge des mille phénomènes !"
  },
  CollectionHall_121395_Desc = {
    Text = "La lame de Mizag te garantira la victoire dans cette partie.\nLe lien entre toi et ton partenaire est inébranlable.\nMême si un jour vous vous retrouvez dans des univers différents, cela ne pourra pas changer."
  },
  CollectionHall_121395_LockTip = {
    Text = "Fin de la connexion multidimensionnelle «Tour inverse»"
  },
  CollectionHall_121395_Title = {
    Text = "Mizag Lame !"
  },
  CollectionHall_121396_Desc = {
    Text = "« Tu n'as pas fait d'entraînement quotidien ? Pourquoi ne pas commencer par une partie de la Carte des Dix Mille Phénomènes ! »\n« Tu n'as pas joué dans la Zone Interdite de Catastrophe de Fusion ? Pourquoi ne pas commencer par une partie de la Carte des Dix Mille Phénomènes ! »\n« C'est un Échecs de Phase, pas une Carte des Dix Mille Phénomènes ! Je vais te montrer mille glands que je vais collecter ! »"
  },
  CollectionHall_121396_LockTip = {
    Text = "Fin de la connexion multidimensionnelle «Tour inverse»"
  },
  CollectionHall_121396_Title = {
    Text = "Jouons ensemble à la Carte des Dix Mille Phénomènes !"
  },
  CollectionHall_121397_Desc = {
    Text = "Appelle mon nom, avant l'aube de l'oubli."
  },
  CollectionHall_121397_LockTip = {
    Text = "Débloqué après avoir terminé la Mission d'enquête·Difficile 9-11"
  },
  CollectionHall_121397_Title = {
    Text = "Venu de l'oubli@2"
  },
  CollectionHall_121398_Desc = {
    Text = "«Viens signer un contrat avec moi et deviens Maître des cartes !»\nCette jeune fille dragon, venue d'un autre monde, t'a lancé une invitation enthousiaste et mystérieuse.\nPour que cet incident dans l'espace de phase revienne à la normale le plus rapidement possible, tu n'as pas d'autre choix."
  },
  CollectionHall_121398_LockTip = {
    Text = "Compléter la connexion multidimensionnelle «Tour inverse»"
  },
  CollectionHall_121398_Title = {
    Text = "propriétaire de l'auberge, Ignatius !"
  },
  CollectionHall_121399_Desc = {
    Text = "Ceux qui viennent plus tard trouveront une telle note de bas de page sous le lourd cadeau. \nLe seul qui a échappé au statut de héros est devenu un héros, et l'enfant qui chérissait ses amis n'en a plus qu'un seul."
  },
  CollectionHall_121399_LockTip = {
    Text = "Terminez le vagabond « Jour du couronnement »"
  },
  CollectionHall_121399_Title = {
    Text = "Je vais agir seul"
  },
  CollectionHall_121400_Desc = {
    Text = "Pars du maître, fais face au maître, défie le maître. \n Ton histoire est inconnue, mais ta mémoire perdurera à travers le temps."
  },
  CollectionHall_121400_LockTip = {
    Text = "Débloquer après avoir terminé l'Opération d'enquête 9-13"
  },
  CollectionHall_121400_Title = {
    Text = "Maître de la folie créatrice"
  },
  CollectionHall_121401_Desc = {
    Text = "Rien n'a plus d'importance, c'est pourquoi tu es ici. \n Tout ce qui est arrivé auparavant, c'est la signification que tu as définie, c'est pourquoi tu es ici."
  },
  CollectionHall_121401_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-13"
  },
  CollectionHall_121401_Title = {
    Text = "existentialisme"
  },
  CollectionHall_121402_Desc = {
    Text = "Le chemin vers eux, le chemin loin d'eux. \n Tout est sur le point de se séparer, tout est sur le point de se terminer, tout est sur le point de commencer. \n L'ombre devant la porte a commencé une longue attente, attendant que la clé d'argent guide ton chemin de retour."
  },
  CollectionHall_121402_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-13"
  },
  CollectionHall_121402_Title = {
    Text = "Chemin menant à eux"
  },
  CollectionHall_121403_Desc = {
    Text = "Les lignes de possibilités d'eux, séparation, convergence, effondrement. \n Jusqu'à l'arrivée du seul sauveur, jusqu'à ce que l'on atteigne enfin la seule fin."
  },
  CollectionHall_121403_LockTip = {
    Text = "Débloqué après avoir terminé la Mission d'enquête·Difficile 9-10"
  },
  CollectionHall_121403_Title = {Text = "unique fin"},
  CollectionHall_121404_Desc = {
    Text = "Le jeune roi a accepté cette transaction. \n Il a dit que mon royaume sera en sécurité."
  },
  CollectionHall_121404_LockTip = {
    Text = "Terminez le vagabond « Jour du couronnement »"
  },
  CollectionHall_121404_Title = {
    Text = "Couronnement"
  },
  CollectionHall_121405_Desc = {
    Text = "Au sein de cette faille spatio-temporelle brisée se tenait autrefois la légendaire Auberge des mille phénomènes. \n Elle reliait autrefois différents univers par des portails, scintillait autrefois sous l'immensité des étoiles et accueillait chaque Maître des cartes. \n Et toi, tu es la preuve que tout cela a existé."
  },
  CollectionHall_121405_LockTip = {
    Text = "Finissez la connexion multidimensionnelle «Tour inverse»"
  },
  CollectionHall_121405_Title = {
    Text = "Au revoir, Maître des cartes !"
  },
  CollectionHall_121406_Desc = {
    Text = "Le Maître te regarde, tu as percé les yeux du Maître."
  },
  CollectionHall_121406_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-13"
  },
  CollectionHall_121406_Title = {
    Text = "Regard de la Fin"
  },
  CollectionHall_121407_Desc = {
    Text = "Guerrier, vengeur, esclave, maître, marchand. \n Même posture ? Posture différente ? Même posture."
  },
  CollectionHall_121407_LockTip = {
    Text = "Débloqué après avoir terminé la Mission d'enquête 9-11"
  },
  CollectionHall_121407_Title = {
    Text = "Chanson de guerre multiple"
  },
  CollectionHall_121408_Desc = {
    Text = "Tu sais, tu ne te bats pas pour de grandes choses. \n Pour sécher les cours, pour les devoirs, pour les desserts, pour les amis, pour le feu, pour passer le temps. \n Tu es simplement une personne ordinaire, prête à mourir pour le quotidien."
  },
  CollectionHall_121408_LockTip = {
    Text = "Débloqué après avoir terminé la Mission d'enquête·Difficile 9-11"
  },
  CollectionHall_121408_Title = {
    Text = "Pour ceux qui meurent habituellement"
  },
  CollectionHall_121409_Desc = {
    Text = "Les animaux, tous les animaux supérieurs, sont inévitablement contrôlés par des comportements sociaux. \n Pourtant, elle se dirigea vers la mort, décomposant ainsi la vérité. \n Une génie folle et sans pareille, elle préférait provoquer elle-même la destruction, offrant aux êtres vivants une délivrance de l'arsenic appelé espoir."
  },
  CollectionHall_121409_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-13"
  },
  CollectionHall_121409_Title = {
    Text = "Déconstruction du comportement communautaire"
  },
  CollectionHall_121410_Desc = {
    Text = "Il envoie des eaux amères et continues du ciel, se rassemblant, se rassemblant. \n Finalement, il s'étendra devant notre chair et notre sang, ce fleuve que nous devons remonter."
  },
  CollectionHall_121410_LockTip = {
    Text = "Terminez le paysage de rêve « Au-delà de l'horizon · bas »"
  },
  CollectionHall_121410_Title = {
    Text = "Rivière de douleur"
  },
  CollectionHall_121411_Desc = {
    Text = "Ils se disent adieu en attendant leurs retrouvailles.\nCar c'est une personne très précieuse, car c'est la mort d'une personne précieuse qui n'est pas destinée."
  },
  CollectionHall_121411_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-11"
  },
  CollectionHall_121411_Title = {
    Text = "La mort d'une personne extrêmement précieuse"
  },
  CollectionHall_121412_Desc = {
    Text = "Faites une pause et reprenez votre souffle. \n Même lorsqu'il s'agit du sujet de l'apocalypse, tout le monde n'a pas la chance de confronter trois mentors aussi influents en même temps."
  },
  CollectionHall_121412_LockTip = {
    Text = "Débloquer après avoir terminé l'Opération d'enquête 9-13"
  },
  CollectionHall_121412_Title = {Text = "Entr'acte"},
  CollectionHall_121413_Desc = {
    Text = "L'histoire de mille glands doit commencer par le premier. \n Dans les Échecs de Phase, chaque fois que vous jouez une carte, \n un éclat de mémoire dorée passe inexplicablement dans les yeux d'Ignatius."
  },
  CollectionHall_121413_LockTip = {
    Text = "Terminer la connexion multidimensionnelle «Tour inverse»"
  },
  CollectionHall_121413_Title = {
    Text = "Recharge illimitée !"
  },
  CollectionHall_121414_Desc = {
    Text = "Folie, prélude à la destruction, c'est la logique sous-jacente d'un monde ordonné. \n Sera-t-il détruit, le monde sera-t-il détruit ? \n Personne ne le sait. \n Mais devant le Créateur, la folie nourrit sa renaissance et celle du monde."
  },
  CollectionHall_121414_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-11"
  },
  CollectionHall_121414_Title = {
    Text = "Fugue folle"
  },
  CollectionHall_121415_Desc = {
    Text = "Quelle est la chose la plus déraisonnable dans le monde ?\nIl n'a aucun but, il n'est pas lié aux griefs et ne peut pas distinguer le bien du mal.\nIl ne désire que réduire en poudre tout ce qui naît dans les rêves au réveil."
  },
  CollectionHall_121415_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-13"
  },
  CollectionHall_121415_Title = {
    Text = "poudre de poisson"
  },
  CollectionHall_121416_Desc = {
    Text = "En tant que ce fragment unique, devenir un dieu est très simple. \n Alors, quel est le prix ?"
  },
  CollectionHall_121416_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête 9-13"
  },
  CollectionHall_121416_Title = {
    Text = "Devenir un dieu"
  },
  CollectionHall_121417_Desc = {
    Text = "Au cours de la longue civilisation humaine, nous avons construit de nombreuses choses. \n Concernant la matière, l'esprit, l'existence, l'amour, la fumée et les conflits. \n Mais ce n'est qu'un bruit insignifiant dans le rêve du Créateur, et une fiction négligée."
  },
  CollectionHall_121417_LockTip = {
    Text = "Débloquer après avoir terminé l'Opération d'enquête 9-13"
  },
  CollectionHall_121417_Title = {
    Text = "Rassemblement fictif"
  },
  CollectionHall_121418_Desc = {
    Text = "Le Gardien de Mizag le plus lâche de l'histoire est mort dans une immense joie."
  },
  CollectionHall_121418_LockTip = {
    Text = "Débloqué après avoir terminé Mission d'enquête·Difficile 9-11"
  },
  CollectionHall_121418_Title = {
    Text = "Héros déterminé à fuir"
  },
  CollectionHall_121898_LockTip = {
    Text = "Débloqué après avoir terminé l'opération d'enquête « Étoiles » 4-0"
  },
  CollectionHall_121898_Title = {
    Text = "Pèlerinage éternel de l'illusion"
  },
  CollectionHall_121901_LockTip = {
    Text = "Débloqué après avoir terminé l'opération d'enquête « Étoiles » 4-16"
  },
  CollectionHall_121901_Title = {
    Text = "Sept jours de la naissance divine"
  },
  CollectionHall_122565_LockTip = {
    Text = "Terminer n'importe quel niveau de l'événement limité « Sacrement enveloppé de brume : Le soi perdu »"
  },
  CollectionHall_122565_Title = {
    Text = "Sacrement enveloppé de brume : Le soi perdu"
  },
  CollectionHall_123756_Title = {
    Text = "Baptême d'argent et de sang"
  },
  CollectionHall_124124_Desc = {
    Text = "Tu as la possibilité de rencontrer un second visage de nombreuses existences, même s'il s'agit d'un nourrisson qui ne devrait pas exister ou de l'un né d'une divinité défectueuse."
  },
  CollectionHall_124124_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête « Étoiles » Chapitre 4-16"
  },
  CollectionHall_124124_Title = {
    Text = "Côté Deux"
  },
  CollectionHall_124125_Desc = {
    Text = "Oh... donc il y a une fin encore pire."
  },
  CollectionHall_124125_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête « Étoiles » Chapitre 4-16"
  },
  CollectionHall_124125_Title = {
    Text = "La mort d'elle, de lui et de lui"
  },
  CollectionHall_124126_Desc = {
    Text = "Comment décririez-vous un compagnon qui s'en va lorsqu'il est trop radieux ? \n Ne décrivez pas leur éclat ; décrivez leurs bras et le parfum de cèdre que vous sentez sur eux."
  },
  CollectionHall_124126_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête « Étoiles » Chapitre 4-16"
  },
  CollectionHall_124126_Title = {Text = "Cedar"},
  CollectionHall_124127_Desc = {
    Text = "À la fin du voyage, tu sais qui t'attend. \n Mais tu n'as pas encore échappé ; tu tombes à nouveau du ciel."
  },
  CollectionHall_124127_LockTip = {
    Text = "Débloquer l'opération d'enquête : Difficile Chapitre Étoiles 4-10"
  },
  CollectionHall_124127_Title = {Text = "chute"},
  CollectionHall_124128_Desc = {
    Text = "Les enfants n'appartiennent pas à la Mère ; ils ont décidé que tout le monde doit rester ici. \n Rester dans leur paradis éternellement doux."
  },
