  },
  CollectionHall_124133_Desc = {
    Text = "Le ciel est sur le point de s'éclaircir, disons adieu à hier.\nAdieu à la douleur, à l'absurdité et à la confusion d'hier,\net accueillons un demain plus lumineux, chacun prenant des chemins séparés."
  },
