  CollectionHall_124133_Title = {
    Text = "Adieu à l'aube"
  },
  CollectionHall_124134_Desc = {
    Text = "Elle a élevé un petit bouclier entre elle et la réalité, entre elle et l'illusion. \n Un bouclier cuit à partir de farine, d'œufs, de citron, de miel, de sucre, de levure chimique et de beurre."
  },
