  CollectionHall_124134_Title = {
    Text = "Bouclier de pâte"
  },
  CollectionHall_124135_Desc = {
    Text = "Le monde est comme d'habitude, avec les enfants dépendant de leurs mères, et les enfants mentant aussi à leurs mères."
