  },
  CollectionHall_124139_Desc = {
    Text = "Un père donne naissance à une fille, et la fille porte le père. \n Illusion, inversion, le destin cyclique dans lequel elle est tombée."
  },
  CollectionHall_124139_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête « Étoiles » Chapitre 4-16"
  },
  CollectionHall_124139_Title = {
    Text = "Grossesse des mensonges de Pervase"
  },
  CollectionHall_124140_Desc = {
    Text = "Qu'est-ce qui pourrait être plus terrifiant que la mort et la douleur ? \n Ce n'est pas une question difficile à répondre pour toi."
  },
  CollectionHall_124140_LockTip = {
