  },
  CollectionHall_124140_Title = {
    Text = "Retourner à l'origine"
  },
  CollectionHall_124141_Desc = {
    Text = "Elle et elle partagent leur dévotion, tandis que lui et lui ont leur rébellion et leur loyauté. \n Elle tisse un grand mensonge, et lui, lui, elle et elle jouent le jeu avec elle. \n À la maison, tout le monde forme une famille douce et inséparable."
  },
