  },
  CollectionHall_124141_Title = {Text = "Foyer"},
  CollectionHall_124142_Desc = {
    Text = "Invoquons le nom du Royaume Divin qui s'élève de la mer—Lémurie, Lémurie."
  },
  CollectionHall_124142_LockTip = {
    Text = "Débloqué après avoir terminé l'Opération d'enquête « Étoiles » Chapitre 4-16"
