  CollectionHall_142155_Desc = {
    Text = "Lorsqu'une créature difforme, incompréhensible, méconnaissable et répugnante s'approche, lancer une Attaque défensive est l'instinct naturel de tout être vivant.\nAinsi, cela ne saurait être considéré comme un péché."
  },
  CollectionHall_142155_LockTip = {
    Text = "Terminer la Connexion multidimensionnelle «Graine d'Amour Oubliée» en difficulté Difficile"
  },
  CollectionHall_142155_Title = {
    Text = "Brutalité innocente"
  },
  CollectionHall_142156_Desc = {
    Text = "«Peux-tu entendre ma voix ? Même si ma silhouette se Fond dans le vent. »\nDe loin, portée par le vent, une voix lance un Appel — traversant un temps immense, depuis une nuit d'hiver vaste et glaciale, une voix venue de l'autre rive de l'Oubli, en quête de réponse."
  },
  CollectionHall_142156_LockTip = {
    Text = "Terminer la Connexion multidimensionnelle «Graine d'Amour Oubliée»"
  },
  CollectionHall_142156_Title = {
    Text = "忘却の彼方"
  },
  CollectionHall_142157_Desc = {
    Text = "Les souvenirs scintillent et se superposent, la vérité ou la fausseté de leur fin reste incertaine.\nMais est-ce vraiment important ?\nAprès tout, toutes les histoires ne commencent pas nécessairement par l'amour, mais elles se terminent toutes par la mort."
  },
  CollectionHall_142157_LockTip = {
    Text = "Terminer la Connexion multidimensionnelle «Graine d'Amour Oubliée»"
  },
  CollectionHall_142157_Title = {
    Text = "Quadruple souvenir"
  },
  CollectionHall_142158_Desc = {
    Text = "Si un jour, vous vous retrouviez comme moi, plongé dans un spectacle de Chair meurtrie, de putréfaction et de décrépitude.\nAlors vous comprendriez certainement —\nL'instant où le bout de ses petits doigts effleure les vôtres est un miracle rare en ce monde."
  },
  CollectionHall_142158_LockTip = {
    Text = "Terminer la Connexion multidimensionnelle «Graine d'Amour Oubliée»"
  },
  CollectionHall_142158_Title = {Text = "Miracle"},
  CollectionHall_142159_Desc = {
    Text = "Vous aussi, êtes-vous las de cette vie ordinaire, cyclique, monotone, qui se répète jour après jour ?\nEssayez quelque chose de nouveau — un autre horizon ouvre grand ses mâchoires et vous adresse une invitation des plus chaleureuses."
  },
  CollectionHall_142159_LockTip = {
    Text = "Terminer la Connexion multidimensionnelle «Graine d'Amour Oubliée»"
  },
  CollectionHall_142159_Title = {
    Text = "Domaine de Sang"
  },
  CollectionHall_142160_Desc = {
    Text = "L'amour est sublime, l'amour est Gourmandise ; l'amour est Bénédiction, l'amour est malédiction.\nL'amour naît avec l'eau, et avec l'eau il disparaîtra.\nMais la saison des pluies ne reviendra plus."
  },
  CollectionHall_142160_LockTip = {
    Text = "Terminer la Connexion multidimensionnelle «Graine d'Amour Oubliée» en difficulté Difficile"
  },
  CollectionHall_142160_Title = {
    Text = "Saison des pluies"
  },
  CollectionHall_142161_Desc = {
    Text = "Toute vie naît dans l'ignorance, puise sa subsistance dans toutes choses, transforme son environnement, pille les ressources et se nourrit elle-même.\nC'est le péché originel auquel nul ne peut échapper."
  },
  CollectionHall_142161_LockTip = {
    Text = "Terminer la Connexion multidimensionnelle «Graine d'Amour Oubliée»"
  },
  CollectionHall_142161_Title = {
    Text = "Péché Originel"
  },
  CollectionHall_142162_Desc = {
    Text = "Il existe une plante appelée pissenlit, qui laisse ses graines voguer au vent.\nSes graines duveteuses errent au gré du vent, si loin, si loin de leur terre natale.\nSeule, quand décidera-t-elle de son destin ?\nC'est lorsqu'il n'y a qu'une seule personne dans le désert qui aime ce pissenlit."
  },
  CollectionHall_142162_LockTip = {
    Text = "Terminer la Connexion multidimensionnelle «Graine d'Amour Oubliée»"
  },
  CollectionHall_142162_Title = {
    Text = "Où va le pissenlit"
  },
  CollectionHall_142163_Desc = {
    Text = "Un vaste ciel, une mer de sable à perte de vue.\nUn territoire sans âme qui vive, rien que toi et moi.\nUne errance amoureuse d'une liberté éternelle."
  },
  CollectionHall_142163_LockTip = {
    Text = "Terminer la Connexion multidimensionnelle «Graine d'Amour Oubliée»"
  },
  CollectionHall_142163_Title = {
    Text = "Errance dans la mer de sable"
  },
  CollectionHall_142164_Desc = {
    Text = "Puis-je appeler ton nom ? Même si le monde disparaît. »\nSi tous les souvenirs devaient sombrer dans l'Annihilation, l'oubli obscur Dévorerait tous les souvenirs que l'on n'a pas eu le temps de chérir.\nAlors prenons-nous la main, et laissons la lumière argentée nous Lier l'un à l'autre.\nDans un nouveau Rêve, au premier printemps où les tendres graines germent."
  },
  CollectionHall_142164_LockTip = {
    Text = "Terminer la Connexion multidimensionnelle «Graine d'Amour Oubliée»"
  },
  CollectionHall_142164_Title = {
    Text = "Song of Memento"
  },
  CollectionHall_142165_Desc = {
    Text = "Chante, ô PV rayonnant qui célèbre la liberté, Séparant le Gynécée de l'espoir jusqu'aux terres les plus lointaines."
  },
  CollectionHall_142165_LockTip = {
    Text = "Terminer la Connexion multidimensionnelle «Graine d'Amour Oubliée» en difficulté Difficile"
  },
  CollectionHall_142165_Title = {
    Text = "Hymne d'ouverture"
  },
  CollectionHall_142868_Desc = {
    Text = "<Title:Introduction>\nPontos se souvient toujours de ce qu'il a ressenti le jour où il a appris l'histoire de sa famille. Avant cela, il n'était jamais prêt à assumer quelque responsabilité que ce soit — tout le monde l'aimait, il était beau, drôle et insouciant.\n@1Les navires qui transitaient sans cesse par le port royal lui évitaient d'affronter la monotonie du quotidien. Il avait entendu tant d'histoires que beaucoup le disaient cultivé, au point qu'il refusait d'admettre qu'il pourrait un jour se fondre dans la masse.\nAinsi fut-il submergé par une joie immense, aussi inattendue que naturelle. Qui plus est, l'entité insondable et grandiose qui se cachait derrière le cauchemar que sa famille avait servi de génération en génération le reconnaissait — il était né différent des autres.\nMais une plaisanterie de « N » poussa des fanatiques à détruire tout un village lors d'une attaque indiscriminée sur la côte.\nIncapable de faire face à ce désastre soudain, pour obtenir la Force des abysses, Pontos choisit de se Sacrifier à @3 — son corps, et toutes ses possibilités.\nMais qu'importe, plus rien ne pourrait jamais échapper à son contrôle.\nIl ne perdrait plus jamais rien."
  },
  CollectionHall_142868_LockTip = {
    Text = "Déverrouillé après avoir Réveillé «Pontos»"
  },
  CollectionHall_142868_Title = {Text = "Pontos"},
  CollectionHall_142901_Title = {
    Text = "Ebwynnos Evermore"
  },
  CollectionHall_143468_Desc = {
    Text = "Le glas a déjà sonné, et les traîtres offrent la représentation la plus Folle.\nD'innombrables fils, quel genre de fin vont-ils tisser —\nC'est à Vous de décider."
  },
  CollectionHall_143468_LockTip = {
    Text = "Terminer la Mission d'enquête · Difficile Chapitre des Étoiles 5-11 pour déverrouiller"
  },
  CollectionHall_143468_Title = {
    Text = "Tisser ensemble le dénouement"
  },
  CollectionHall_143469_Desc = {
    Text = "Venez vite, venez vite, Tout le monde vous attend.\nParcourez le long couloir, montez sur la scène éternelle.\nVous êtes bien le seul et unique protagoniste de toute la pièce."
  },
  CollectionHall_143469_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143469_Title = {
    Text = "Spirale sans fin"
  },
  CollectionHall_143470_Desc = {
    Text = "Ils chantent ensemble, chacun remplit son rôle.\nMais ils sont tous Elle.\nC'est son monologue sans fin, qui ne connaît jamais la Chute du rideau."
  },
  CollectionHall_143470_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143470_Title = {
    Text = "Spectacle de solo"
  },
  CollectionHall_143471_Desc = {
    Text = [[
Act I : Filage
Act II : Mesure
Act III : Tranchement
Ainsi de suite, ainsi de suite...]]
  },
  CollectionHall_143471_LockTip = {
    Text = "Terminer la Mission d'enquête · Difficile Chapitre des Étoiles 5-11 pour déverrouiller"
  },
  CollectionHall_143471_Title = {
    Text = "Pièce en trois actes"
  },
  CollectionHall_143472_Desc = {
    Text = "Rien qu'un jeune homme plein de Ferveur, qui a tiré un coup de feu à un coin de rue ordinaire.\nDu moins, c'est ce que Tout le monde pensait à ce moment-là."
  },
  CollectionHall_143472_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143472_Title = {
    Text = "[Prologue] du Feu de la Guerre"
  },
  CollectionHall_143473_Desc = {
    Text = "Grincement, grincement.\nÔ Destin, ta roue tourne sans relâche.\nLa pauvreté et le pouvoir sont tous deux fondus par toi comme de la glace.\nTu te voiles toi-même et dissimules ton visage,\npourtant tu brilles aussi vers moi......"
  },
  CollectionHall_143473_LockTip = {
    Text = "Terminer la Mission d'enquête · Difficile Chapitre des Étoiles 5-11 pour déverrouiller"
  },
  CollectionHall_143473_Title = {
    Text = "Ô Destin, que tu es cruel"
  },
  CollectionHall_143474_Desc = {
    Text = "Au revoir, dans la mélodie finale.\nAu revoir, sous le regard du Destin.\nLe protagoniste de l'histoire s'apprête à entamer un nouveau voyage."
  },
  CollectionHall_143474_LockTip = {
    Text = "Terminer la Mission d'enquête · Difficile Chapitre des Étoiles 5-11 pour déverrouiller"
  },
  CollectionHall_143474_Title = {
    Text = "Et je chante encore"
  },
  CollectionHall_143475_Desc = {
    Text = "Ma chère, laissons-nous porter par l'ivresse et dansons encore une fois ensemble."
  },
  CollectionHall_143475_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143475_Title = {
    Text = "Bal Légèrement ivre"
  },
  CollectionHall_143476_Desc = {
    Text = "L'Audience verse des larmes pour la séparation, et aussi pour la Rencontre à nouveau.\nEt les prisonnières au centre de la scène devraient également s'offrir mutuellement des applaudissements."
  },
  CollectionHall_143476_LockTip = {
    Text = "Terminer la Mission d'enquête · Difficile Chapitre des Étoiles 5-11 pour déverrouiller"
  },
  CollectionHall_143476_Title = {
    Text = "Le Prisonnier fait ses adieux"
  },
  CollectionHall_143477_Desc = {
    Text = "Les gens aiment attribuer une guerre à Un coup de feu.\nMais le Destin ricane — c'est là l'illusion collective de toute l'humanité."
  },
  CollectionHall_143477_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143477_Title = {
    Text = "Quand le Papillon Bat des Ailes"
  },
  CollectionHall_143478_Desc = {
    Text = "Une représentation sans épilogue est incomplète.\nModifier légèrement les répliques, ajuster les décors, alterner les acteurs — chaque rappel est un acte entièrement nouveau."
  },
  CollectionHall_143478_LockTip = {
    Text = "Terminer la Mission d'enquête · Difficile Chapitre des Étoiles 5-11 pour déverrouiller"
  },
  CollectionHall_143478_Title = {
    Text = "Variation en rappel"
  },
  CollectionHall_143479_Desc = {
    Text = "La plume court sur le papier blanc, poursuivant les mots, et les mots mènent à une conclusion déjà écrite d'avance.\nTout cela se produit avant que vous n'ouvriez chaque livre."
  },
  CollectionHall_143479_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143479_Title = {
    Text = "Ce qui sera décidé, ce qui a été décidé"
  },
  CollectionHall_143480_Desc = {
    Text = "Un peu d'amer, 20 ml de vermouth doux, un peu de xérès, rempli de glace et remué — voilà un excellent apéritif, et une pièce jouée cinq cents fois."
  },
  CollectionHall_143480_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143480_Title = {Text = "Adonis"},
  CollectionHall_143481_Desc = {
    Text = "Si vous traitez le Destin comme un pitre, vous ne serez pas asservi par lui.\nAccueillez-Le avec un rire qui ne s'arrête jamais, et appelons ensemble Son nom —\nPlaisir."
  },
  CollectionHall_143481_LockTip = {
    Text = "Terminer la Mission d'enquête · Difficile Chapitre des Étoiles 5-11 pour déverrouiller"
  },
  CollectionHall_143481_Title = {
    Text = "L'arrivée du bouffon"
  },
  CollectionHall_143482_Desc = {
    Text = "«Je vous hais, je vous hais de vous être fait votre propre Cocon, je vous hais d'être impuissant, je vous hais de vous être abandonné vous-même.»\n«......Pourtant cette haine me consume aussi, car, je vous aime également.»"
  },
  CollectionHall_143482_LockTip = {
    Text = "Terminer la Mission d'enquête · Difficile Chapitre des Étoiles 5-11 pour déverrouiller"
  },
  CollectionHall_143482_Title = {
    Text = "Élégie du spectre vengeur"
  },
  CollectionHall_143483_Desc = {
    Text = "Le monde vous offre d'innombrables embranchements, mais ils confluent en un même point — nommé Destruction, nommé Fin."
  },
  CollectionHall_143483_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143483_Title = {
    Text = "Copie du Monde"
  },
  CollectionHall_143484_Desc = {
    Text = "Le rideau se lève et retombe, les spectacles se succèdent, elle demeure dans le théâtre — elle est dramaturge, L'Audience, et aussi actrice.\nÔ maîtresse du Destin, tu es si cruelle, éternellement silencieuse, mais pourquoi donc verses-tu des larmes ?"
  },
  CollectionHall_143484_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143484_Title = {
    Text = "La Pièce du Destin Tissé"
  },
  CollectionHall_143485_Desc = {
    Text = "Si la Destruction est inévitable en fin de compte, déchirer le filet du Destin permettrait-il d'atteindre une véritable Rédemption ?\nNul ne peut répondre, aucun dieu ne peut répondre.\nMais au moins, les souffrances infinies disparaîtront elles aussi."
  },
  CollectionHall_143485_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143485_Title = {
    Text = "Représentation sacrilège"
  },
  CollectionHall_143486_Desc = {
    Text = "Ces visages qui évoluent dans le monde, si réels, si libres en apparence, ne sont que des accessoires fixes sur une scène.\nChaque geste, chaque mouvement, guidé par les fils du Destin."
  },
  CollectionHall_143486_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143486_Title = {
    Text = "Les Fils de Toutes Choses"
  },
  CollectionHall_143487_Desc = {
    Text = "Au réveil, tout disparaîtra, complètement oublié — le manoir, le jardin fleuri, les chansons, les peintures...\nC'était un printemps qui n'existait pas."
  },
  CollectionHall_143487_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143487_Title = {
    Text = "Le Rêve tissé du printemps"
  },
  CollectionHall_143488_Desc = {
    Text = "Les cordes s'élèvent doucement, la Servante chante.\nCelle qui se tenait dans les coulisses vient au devant de la scène, elle vous salue et vous invite à Témoigner de la trajectoire du destin déjà tracée."
  },
  CollectionHall_143488_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143488_Title = {
    Text = "Soulever son Voile"
  },
  CollectionHall_143489_Desc = {
    Text = "C'est une danse improvisée que l'on ne peut interpréter qu'une seule fois dans sa vie.\nMais peu importe, elle aura la chance de devenir un échantillon, figée pour l'éternité."
  },
  CollectionHall_143489_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143489_Title = {
    Text = "Ballet : «La Mort du Cygne»"
  },
  CollectionHall_143490_Desc = {
    Text = "Le rideau s'ouvre, des personnages absurdes défilent tour à tour.\nIls chantent, elles dansent, avant que le Destin ne s'abatte, ils s'acharnent à porter la pièce sur scène, même si le dénouement était déjà écrit."
  },
  CollectionHall_143490_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143490_Title = {
    Text = "Duo au Lever de Rideau"
  },
  CollectionHall_143491_Desc = {
    Text = "Pour que tout reste sur la bonne voie, certaines choses doivent toujours être écartées, rejetées.\nLes existences non choisies tombent toutes dans un abîme de ténèbres, leurs lamentations et leurs malédictions ne seront jamais entendues de personne."
  },
  CollectionHall_143491_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143491_Title = {
    Text = "Le « Je » Abandonné"
  },
  CollectionHall_143492_Desc = {
    Text = "Mourir ainsi, quelle beauté. Elle pensa."
  },
  CollectionHall_143492_LockTip = {
    Text = "Terminer la Mission d'enquête Chapitre des Étoiles 5-16 pour déverrouiller"
  },
  CollectionHall_143492_Title = {
    Text = "La plus belle des expiations"
  },
  CollectionHall_143592_LockTip = {
    Text = "Terminer n'importe quel Niveau de la Plongée dans l'inconscient «Ebwynnos Evermore» pour déverrouiller"
  },
  CollectionHall_143592_Title = {Text = "Addiction"},
  CollectionHall_144377_Desc = {
    Text = "Au cours des longs éons de sa veille, Tawil posa un jour le pied dans un royaume mortel.\nInvisible, elle arpenta les marges du monde des mortels, observant silencieusement les actes de chaque être vivant.\n\nPar une nuit ordinaire, une dense mer de lumières à la périphérie de la ville attira son regard.\nDes décors de scène, des chants et des danses, des marchands proposant des pâtisseries, des enfants s'ébattant, des oisifs levant leurs coupes en joyeux toasts. C'était le souffle même de la vie, un fugace moment de répit.\nEnchantée, elle ne put s'empêcher de prendre forme mortelle.\n\n« Bonjour. Une peinture en sucre, s'il vous plaît. »\n« Tout de suite, mademoiselle. Que dois-je dessiner pour vous ? »\nTawil inclina doucement la tête. Elle se souvint seulement de tendre les pièces sans propriétaire qu'elle avait trouvées par hasard, oubliant entièrement qu'elle pouvait exprimer un souhait de sa propre voix.\n« Si vous n'arrivez pas à vous décider, que diriez-vous que je vous dessine à votre image ? Vous êtes belle comme une déesse. »\nTawil sourit et acquiesça. Le marchand lança un joyeux appel, souleva une louche de sucre fondu et commença à peindre.\n\n<Italic:Drip. Drip.>\nCe qui tomba sur la dalle de pierre n'était pas un sirop couleur de miel.\nMais de la pluie — une pluie noire.\nUn ichor noir dégoulinait d'une hauteur insondable, faisant fondre une horrible fissure à travers le ciel.\n\nAlors, Tawil commença à tomber vers le haut.\nC'était le monde qui sombrait. Le sourire du marchand se figea dans sa mémoire, puis se noya avec tout le reste dans l'océan noir. Tout fut réduit à un simple point parmi d'innombrables étoiles mortes, se fondant dans un passé à jamais hors de sa portée.\nC'était le bouleversement qu'elle avait causé, et la rétribution qu'elle était destinée à porter.\nElle regardait au loin, silencieuse et immobile. Elle continuait simplement à tomber vers le haut.\nCar c'était l'endroit qu'elle était destinée à garder — la Porte d'Argent qui « transcende le temps et l'espace ».\nIci, elle monterait la garde, pour toute l'éternité."
  },
  CollectionHall_144377_Title = {
    Text = "Descente Ascendante"
  },
  CollectionHall_144448_Desc = {
    Text = "On vous avait promis une utopie inaccessible, où résident toutes les chères vieilles âmes de votre mémoire."
  },
  CollectionHall_144448_LockTip = {
    Text = "Terminer la Plongée dans l'inconscient «Ebwynnos Evermore»"
  },
  CollectionHall_144448_Title = {
    Text = "Vieilles âmes"
  },
  CollectionHall_144449_Desc = {
    Text = "Les vivants cherchaient désespérément un cénotaphe où pleurer.\nLes morts, eux, étaient simplement morts."
  },
  CollectionHall_144449_LockTip = {
    Text = "Terminer la Plongée dans l'inconscient «Ebwynnos Evermore»"
  },
  CollectionHall_144449_Title = {
    Text = "Les Cicatrices du cénotaphe"
  },
  CollectionHall_144450_Desc = {
    Text = "Le soleil a glissé sous la marée, le dernier fil de lumière voilé derrière lui.\nL'aube et le crépuscule échangeront leurs places au prochain souffle, et il gardera toutes choses ici telles qu'elles sont."
  },
  CollectionHall_144450_LockTip = {
    Text = "Terminer la Plongée dans l'inconscient «Ebwynnos Evermore» en difficulté Difficile"
  },
  CollectionHall_144450_Title = {
    Text = "Le soleil qui sombre"
  },
  CollectionHall_144451_Desc = {
    Text = "La lune glousse, la lune chuchote.\nDestin, ô destin, dit la lune — le destin est sur le point de tomber."
  },
  CollectionHall_144451_LockTip = {
    Text = "Terminer la Plongée dans l'inconscient «Ebwynnos Evermore»"
  },
  CollectionHall_144451_Title = {
    Text = "La Lune qui tombe"
  },
  CollectionHall_144452_Desc = {
    Text = "Sans le vouloir, il avait amené les gens à lui confier quelque chose.\nSans le vouloir, il avait laissé quelque chose derrière lui, tout comme eux."
  },
  CollectionHall_144452_LockTip = {
    Text = "Terminer la Plongée dans l'inconscient «Ebwynnos Evermore»"
  },
  CollectionHall_144452_Title = {Text = "Leur Éros"},
  CollectionHall_144453_Desc = {
    Text = "Pour le banc de poissons, quitter la mer ne signifie rien d'autre que l'asphyxie."
  },
  CollectionHall_144453_LockTip = {
    Text = "Terminer la Plongée dans l'inconscient «Ebwynnos Evermore» en difficulté Difficile"
  },
  CollectionHall_144453_Title = {
    Text = "Prisonnier de la mer"
  },
  CollectionHall_144454_Desc = {
    Text = "Insensé, superficiel, vaniteux, solitaire — le fragile despote a forgé un royaume qui lui est propre.\nLes carapaces immuables ne respirent aucune vérité ; car rien ne peut reconstituer, depuis le ravin, un cœur trop craintif face au changement — et ainsi brisé avant l'heure."
  },
