  CollectionHall_144476_Desc = {
    Text = "Que cette danse éphémère devienne éternelle au sein du fleuve du temps.\nÀ la prochaine Fête de l'An, nous nous retrouverons sous la lumière de la lune.\n*<Italic:Un père et sa fille... comme c'est touchant>. (ノへ￣、)"
  },
