  CollectionHall_147989_Desc = {
    Text = "Du temps où j'étais encore le plus humble des serviteurs, je fus un jour témoin d'une campagne d'une cruauté absolue.\nCette maîtresse légendaire — le pouvoir avait forgé sa chair et ses os, son sang bouillonnant était devenu une flamme impérissable, et cette lueur avait à son tour embrasé ses yeux —\nGarde ce souvenir vivant pour moi, mon enfant... En fin de compte, elle triompha et conquit la mer des étoiles."
  },
