  CollectionHall_48635_Desc = {
    Text = "<Title:Profile>\nDoyenne intérimaire de Mythag.\nApprentie sous Crowley McKinnon, un junior direct de Herbert.\nTémoin du meurtre de leur mentor par Herbert, elle gère les affaires de l'académie depuis la mort du mentor.\nUne véritable fanatique de l'efficacité, elle n'est jamais en retard et garde les cheveux courts pour gagner du temps sur les soins personnels.\nFuit son pays d'origine dévasté par la guerre, Elche, pour Leo.\nSon index droit ne peut pas se plier correctement, prétendument en raison d'un traitement brutal dans un camp de concentration."
  },
  CollectionHall_48635_LockTip = {
    Text = "Déverrouille après avoir complété le Prologue"
  },
  CollectionHall_48635_Title = {Text = "Czort"},
  CollectionHall_48636_Desc = {
    Text = "<Title:Introduction>\nL'une des trois fondatrices, aux côtés de Ward Phillips et Kralarques, a établi le prédécesseur de l'Université Mythag—le Collège Mythag.\nElle est la première \"Réveillante\" et la source de la technologie des Réveillants.\nGardant le Bassin Noir pendant de nombreuses années, très peu de gens ont vu son visage, faisant d'elle l'un des plus grands secrets de l'Université Mythag.\n\"Chut... ne sonde pas ton @2.\""
  },
