  },
  CollectionHall_48947_Title = {Text = "Maturité"},
  CollectionHall_48948_Desc = {
    Text = "Chut... Arrête ici, arrête avec moi.\nNe cherche pas à connaître son origine"
  },
  CollectionHall_48948_Title = {
    Text = "Gourmandise"
  },
  CollectionHall_48949_Desc = {
    Text = "Homonculus au-dessus, vous offrant un réceptacle pur et parfait."
  },
  CollectionHall_48949_Title = {
