  CollectionHall_51019_Desc = {
    Text = "<Title:Date de fondation>\nAvant le Grand Déluge\n\n<Title:Fondateur>\nInconnu\n\n<Title:Aperçu>\nUn peuple nomade qui s'est scindé de l'Empire assyrien.\nCachés au milieu des tempêtes violentes du Désert de Lemwash, ils vivent de manière très primitive, communiquant rarement avec des étrangers. Le peuple Aram vénère l'\"Arbre Mère de l'Abondance,\" comptant sur ses extraordinaires capacités de reproduction ainsi que sur l'eau sacrée de la rivière pour maintenir leur échelle de population.\nAprès l'\"Incident de Lemwash,\" le peuple Aram a disparu sans laisser de traces, sans nouvelles ultérieures."
  },
