  CollectionHall_62184_Desc = {
    Text = "<Title:Introduction>\nChef d'orchestre et musicien de renommée mondiale. Malgré son apparence juvénile, ses performances symphoniques ont fait le tour du monde, se vendant toujours à guichet fermé.\nEn tant que génie acclamé dans la musique classique, les informations personnelles de Hameln restent inconnues, attirant l'attention du Comité. À travers une enquête prolongée, ils ont découvert que les lieux de performance de Hameln se chevauchaient de manière significative avec les activités de l'Église de la Lumière du Temple.\nAvant qu'ils ne puissent découvrir la vérité, cela leur est venu à l'esprit : pendant l'invasion de Mythag par l'Église de la Lumière du Temple, Hameln a joué un rôle clé.\nCe n'est qu'alors que les gens ont réalisé que la véritable scène de ce prodige musical avait toujours été au-delà du théâtre."
  },
  CollectionHall_62184_LockTip = {
    Text = "Débloquez après avoir terminé l'Opération Chapitre 8 \"Symphonie Finale\""
  },
  CollectionHall_62184_Title = {Text = "Hamelin"},
