  CollectionHall_89385_Desc = {
    Text = "Le sang et la chair volent, les lames tranchantes dansent sauvagement, les monstres chantent bruyamment dans des mots incompréhensibles. La seule pensée qui reste dans le cerveau enragé est—capturez-la, à tout prix, capturez-la."
